function Answer({data}){return <><h2>{data.lead}</h2><p>{data.intro}</p>{data.sections.map(([title,items])=><section key={title}><h3>{title}</h3><ul>{items.map(x=><li key={x}>{x}</li>)}</ul></section>)}<div className="answer-end">{data.end}</div></>}
function MotionButton({icon:Icon,size=18,children,className='',...props}){
 const icon=useRef(null);
 const start=()=>{if(!props.disabled)icon.current?.startAnimation()};
 const stop=()=>icon.current?.stopAnimation();
 return <button {...props} className={className} onMouseEnter={start} onMouseLeave={stop} onFocus={start} onBlur={stop}><Icon ref={icon} size={size}/>{children}</button>;
}
function TextShimmer({children,duration=1,className=''}){return <span className={'text-shimmer '+(className||'')} style={{'--shimmer-duration':duration+'s'}}>{children}</span>}
