 const dataFor=(i,turn=current)=>{const p=turn.plans[i];if(p.text!==undefined)return{type:'streamed',text:p.text,error:p.error,status:p.status,source:p.source};return turn.modality==='image'?{type:'image',asset:imageSample(p).id+'.png',description:imageSample(p).alt,source:'预置图片演示'}:turn.modality==='code'?{type:'code',code:codeSample(p).code,title:codeSample(p).title,lang:codeSample(p).lang,source:'预置代码演示'}:CONTENT[turn.kind][i%3]};
